def validate(tool_input, schema):
    """Return a list of problems; an empty list means valid.
    Checks required keys, unexpected keys, and keys whose schema type is "string"."""
    problems = []
    for key in schema.get("required", []):
        if key not in tool_input:
            problems.append(f"missing required property '{key}'")
    props = schema.get("properties", {})
    for key, value in tool_input.items():
        if key not in props:
            problems.append(f"unexpected property '{key}'")
        elif props[key].get("type") == "string" and not isinstance(value, str):
            problems.append(f"'{key}' must be a string")
    return problems


def dispatch(tools, name, tool_input):
    """tools maps a tool name to (schema, run). Validate, then execute.
    Always return a string the loop can feed back to the model; never raise."""
    if name not in tools:
        return f"error: unknown tool '{name}'"
    schema, run = tools[name]
    problems = validate(tool_input, schema)
    if problems:
        return "error: invalid input: " + "; ".join(problems)
    try:
        return run(tool_input)
    except Exception as e:
        return f"error: {type(e).__name__}: {e}"
